const out = [];
for (const [idx, item] of $input.all().entries()) {
  const root = item.json, raw = root.body || root;
  const values = raw.entry ? raw.entry.flatMap(e => (e.changes || []).filter(c => c.field === 'messages').map(c => c.value)) : [raw];
  for (const v of values) {
    if (v.metadata?.phone_number_id && String(v.metadata.phone_number_id) !== String(root.waPhoneNumberId)) continue;
    for (const m of (v.messages || [])) {
      if (m.from !== 'CONFIGURE_WHATSAPP_ALLOWED_NUMBER' || !m.id || typeof m.type !== 'string') continue;
      const wa = { from:m.from, wamid:m.id, tipo:m.type, phone_number_id:root.waPhoneNumberId, context_id:m.context?.id || null };
      const msg = { message_id:m.id, date:Number(m.timestamp) || 0, chat:{id:123456789,type:'private'}, from:{id:123456789} };
      const u = { update_id:'wa_'+m.id, canal:'whatsapp', wa, message:msg };
      if (m.context?.id) msg.reply_to_message = { message_id:m.context?.id, text:m.context?.text?.body || m.context?.text || '' };
      let soportado = true;
      if (m.type === 'text' && typeof m.text?.body === 'string') msg.text = m.text.body;
      else if (['audio','image','document'].includes(m.type) && m[m.type]?.id) {
        const media = m[m.type], mime = media.mime_type || (m.type === 'image' ? 'image/jpeg' : 'audio/ogg');
        wa.media_id = media.id; wa.mime_type = mime;
        const f = {file_id:media.id, file_unique_id:media.sha256 || media.id, mime_type:mime};
        if (m.type === 'audio' && mime.startsWith('audio/')) msg.voice = f;
        else if (m.type === 'image' && mime.startsWith('image/')) msg.photo = [f];
        else if (m.type === 'document' && /^(image\/|application\/pdf$)/.test(mime)) msg.document = {...f,file_name:media.filename || ''};
        else soportado = false;
        if (m.type !== 'audio' && media.caption) msg.caption = media.caption;
      } else if (m.type === 'interactive') {
        const data = m.interactive?.button_reply?.id || m.interactive?.list_reply?.id;
        if (!/^(?:pc:[^:]+:[^:]+|a:pc:[^:]+:[^:]+|r:[fa]:[a-zA-Z0-9_-]{1,55})$(?![\s\S])/.test(data || '') || (!/^r:/.test(data) && !m.context?.id)) continue;
        delete u.message;
        u.callback_query = {id:m.id,from:{id:123456789},data,message:{...msg,message_id:m.context?.id,text:m.context?.text?.body || m.context?.text || ''}};
      } else soportado = false;
      out.push({json:{update:u,soportado,wa_context_wamid: u.callback_query?.data.startsWith('r:') ? null : (wa.context_id || null)},pairedItem:{item:idx}});
    }
  }
}
return out;

// A Get omits missing rows in mixed batches. Recover every original input, including
// text replies without a saved row; missing callback contexts still stop silently.
const inputs = $input.all();
const direct = inputs.every(i => i.json.update);
const originals = direct ? inputs : $('¿Tiene contexto?').all(0);
if (!direct) for (const item of inputs) {
  if (item.json.error) throw new Error('No se pudo leer el contexto WhatsApp');
  if (item.json.datos !== undefined && !originals.some(i => i.json.wa_context_wamid === item.json.wamid))
    throw new Error('Contexto WhatsApp de otro mensaje');
}
const out = [];
for (const [index, item] of originals.entries()) {
  const a = item.json;
  const rowIndex = direct ? index : inputs.findIndex(i => i.json.wamid === a.wa_context_wamid);
  const r = direct ? {} : (inputs[rowIndex]?.json || {});
  const restore = () => {
const u = JSON.parse(JSON.stringify(a.update));
// El Router valida estos IDs con su static data, sin tabla de contexto.
if (/^r:[fa]:[a-zA-Z0-9_-]{1,55}$/.test(u.callback_query?.data || '')) return {json:u};
if (r.error) throw new Error('No se pudo leer el contexto WhatsApp');
let ctx = null;
if (a.wa_context_wamid && r.datos !== undefined) {
  if (r.wamid !== a.wa_context_wamid) throw new Error('Contexto WhatsApp de otro mensaje');
  try { ctx = JSON.parse(r.datos);
    if (!ctx || typeof ctx !== 'object' || Array.isArray(ctx)) throw new Error(); } catch (e) { throw new Error('Contexto WhatsApp inválido'); }
  if (ctx.from !== u.wa.from || String(ctx.phone_number_id) !== String(u.wa.phone_number_id)) throw new Error('Contexto WhatsApp de otro destinatario');
}
if (u.callback_query) {
  // A webhook context carries only a wamid, not the question. Validate against the saved message.
  const data = String(u.callback_query.data || '').replace(/^a:/, '');
  if (!/^pc:[^:]+:[^:]+$/.test(data)) return null;
  const [, id, valor] = data.split(':');
  if (!ctx || String(ctx.confirmacion) !== id || !(ctx.botones || []).some(b => String(b.valor) === valor)) return null;
  u.callback_query.message.text = ctx.texto || '';
} else if (u.message.reply_to_message && ctx) {
  u.message.reply_to_message.text = ctx.texto || '';
  u.wa.reply_confirmacion = ctx.confirmacion || null;
}
return { json:u };
  };
  const restored = restore();
  if (restored) out.push({ ...restored, pairedItem: { item: Math.max(0, rowIndex) } });
}
return out;
